/// Cash-or-nothing call: pays `cash` if S_T > K.
inline double digital_call(double S, double K, double r, double sigma, double T, double cash) {
    double sq = sigma * qt::py::math_sqrt(T);
    double b = qt::py::truediv(qt::py::math_log(qt::py::truediv(S, K)) + (r - 0.5 * sigma * sigma) * T, sq);
    return cash * qt::py::math_exp(-r * T) * qt::norm_cdf(b);
}

/// Discretely monitored geometric-average Asian call (Kemna-Vorst style closed form)
/// with n_fix equally spaced fixings ending at T.
inline double geometric_asian_call(double S, double K, double r, double sigma, double T, long long n_fix) {
    if (n_fix < 1) {
        throw qt::ValueError("need at least one fixing");
    }
    long long n = n_fix;
    // mean and variance of the log of the geometric average
    const double left = qt::py::math_log(S);
    double mu = left + [&] { const double lhs2 = [&] { const double lhs = (r - 0.5 * qt::py::power(sigma, 2.0)) * T; return lhs * static_cast<double>(qt::iadd(n, 1LL)); }(); return qt::py::truediv(lhs2, static_cast<double>(qt::imul(2LL, n))); }();
    const double left2 = qt::py::power(sigma, 2.0) * T;
    const double left3 = left2 * static_cast<double>(qt::iadd(n, 1LL));
    const double left4 = left3 * static_cast<double>(qt::iadd(qt::imul(2LL, n), 1LL));
    double var = qt::py::truediv(left4, static_cast<double>(qt::imul(qt::imul(6LL, n), n)));
    double sd = qt::py::math_sqrt(var);
    double a = qt::py::truediv(mu - qt::py::math_log(K) + var, sd);
    const double left5 = qt::py::math_exp(-r * T);
    return left5 * (qt::py::math_exp(mu + 0.5 * var) * qt::norm_cdf(a) - K * qt::norm_cdf(a - sd));
}

/// Cox-Ross-Rubinstein binomial price of a European option, summed directly over
/// terminal nodes. Binomial weights are built in log space so 1000+ steps don't overflow.
inline double crr_european(double S, double K, double r, double sigma, double T, long long steps, bool is_call) {
    if (steps < 1) {
        throw qt::ValueError("steps must be at least 1");
    }
    double dt = qt::py::truediv(T, static_cast<double>(steps));
    double u = qt::py::math_exp(sigma * qt::py::math_sqrt(dt));
    double d = qt::py::truediv(1.0, u);
    double p = qt::py::truediv(qt::py::math_exp(r * dt) - d, u - d);
    if (!(0 < p && p < 1)) {
        throw qt::ValueError("risk-neutral probability outside (0, 1): reduce the step size");
    }
    double log_p = qt::py::math_log(p);
    double log_q = qt::py::math_log1p(-p);
    double total = 0.0;
    double log_choose = 0.0;  // log C(steps, k), updated incrementally
    for (long long k = 0; k < qt::iadd(steps, 1LL); ++k) {
        if (k > 0) {
            const double left = qt::py::math_log(qt::iadd(qt::isub(steps, k), 1LL));
            log_choose += left - qt::py::math_log(k);
        }
        const double left2 = S * qt::py::power(u, static_cast<double>(k));
        double ST = left2 * qt::py::power(d, static_cast<double>(qt::isub(steps, k)));
        double payoff = is_call ? std::max(ST - K, 0.0) : std::max(K - ST, 0.0);
        if (payoff > 0) {
            total += qt::py::math_exp(log_choose + static_cast<double>(k) * log_p + static_cast<double>(qt::isub(steps, k)) * log_q) * payoff;
        }
    }
    return qt::py::math_exp(-r * T) * total;
}

